mapper.select:
select

from media_upload_task
where bucket_name = #{bucketName}
and md5 = #{md5}
and file_size = #{fileSize}
and status = 0
and is_deleted = 0
order by id desc
limit 1

mapper.update:
update media_upload_task
set status = #{status}
where id = #{id}
  and is_deleted = 0

update media_upload_task
set status        = #{status},
    media_file_id = #{mediaFileId}
where id = #{id}
  and is_deleted = 0
